/* From Uiverse.io by JasonMep - Tags: button */
.__UIV_SCOPE__ .button {
 color: #ecf0f1;
 font-size: 17px;
 background-color: #e67e22;
 border: 1px solid #f39c12;
 border-radius: 5px;
 padding: 10px;
 box-shadow: 0px 6px 0px #d35400;
 transition: all .1s;
}

.__UIV_SCOPE__ .button:active {
 box-shadow: 0px 2px 0px #d35400;
 position: relative;
 top: 2px;
}
